from abc import ABC, abstractmethod
from dirhunt.pool import Pool


class SourceInterface(ABC):
    """Abstract base class for all source providers."""

    @abstractmethod
    def add_domain(self, domain):
        """Add a domain to be scanned."""
        pass

    @abstractmethod
    def callback(self, result):
        """Process a result from the source."""
        pass

    @abstractmethod
    def add_result(self, result):
        """Add a result to be processed."""
        pass

    @abstractmethod
    def add_error(self, error):
        """Add an error to be handled."""
        pass


class SessionFactoryInterface(ABC):
    """Interface for session creation."""

    @abstractmethod
    def create_session(self):
        """Create and return a new session object."""
        pass


class ProcessorInterface(ABC):
    """Interface for URL processors."""

    @abstractmethod
    def is_applicable(self, crawler_url):
        """Check if this processor applies to the given CrawlerUrl."""
        pass

    @abstractmethod
    def process(self, crawler_url):
        """Process the given CrawlerUrl."""
        pass


class UrlInfoInterface(ABC):
    """Interface for URL information retrieval."""

    @abstractmethod
    def get_data(self, url):
        """Get data for the given URL."""
        pass


class CrawlerUrlInterface(ABC):
    """Interface for CrawlerUrl operations."""

    @abstractmethod
    def start(self):
        """Start processing the URL."""
        pass

    @abstractmethod
    def result(self):
        """Get the result of processing."""
        pass


class DirectoryListInterface(ABC):
    """Interface for directory list detection and parsing."""

    @abstractmethod
    def is_applicable(self, content_type, content):
        """Check if this directory list applies to the given content."""
        pass

    @abstractmethod
    def get_links(self, content):
        """Extract links from the given content."""
        pass
